/**
 * The sheet's today was changed and saved; published inside the change, before the figures it moves are
 * announced, so what follows from the new today is part of the same change. No audit line of its own.
 */
public record TodayChanged(String sheetId, String user, LocalDate today) {
}
-- The whole sheet as it stood at the end of a day: written when the sheet's today moves on from that day,
-- holding (as JSON) every row of the sheet in every table, so the screen can show the sheet as of a date
-- gone by. The latest one written for a day on or before the date is the sheet as it stood then.
CREATE TABLE sheet_past (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    ended_on DATE         NOT NULL,
    state    CLOB         NOT NULL
);
CREATE INDEX sheet_past_sheet ON sheet_past (sheet_id, ended_on, id);
-- A setting that carries a figure (the clerk limit, the floor, the terms and each grade's own terms, the
-- late percent, the cap) is dated: each value is in force from its from-date, a value with no from-date
-- from the beginning of time. A value is kept as written; null is a value saved blank (no limit, the
-- starting value, or the sheet's terms). A key has at most one value per from-date.
CREATE TABLE sheet_setting (
    id            BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id      VARCHAR(100) NOT NULL REFERENCES sheet (id),
    setting_key   VARCHAR(40)  NOT NULL,
    from_date     DATE,
    setting_value VARCHAR(40),
    from_key      DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01')),
    CONSTRAINT sheet_setting_key_from_unique UNIQUE (sheet_id, setting_key, from_key)
);
-- The values a sheet already has hold from the beginning of time.
