ALTER TABLE sheet DROP COLUMN due_floor;
ALTER TABLE sheet DROP COLUMN terms;
ALTER TABLE sheet DROP COLUMN terms_a;
ALTER TABLE sheet DROP COLUMN terms_b;
ALTER TABLE sheet DROP COLUMN terms_c;
